    async fn record_scope_boundary(
        &self,
        index: &[ChildScopeRef],
        read_scope_seed: &[u8; SECRET_LEN],
    ) -> Result<(), ResolveFailure> {
        let identity = self.owner.verifying_key();
        for child in index {
