            self.http,
            self.floors,
            self.owner_enc_secret,
            identity,
            self.scope_id,
        );
        match self.parent_node_seed {
            Some(seed) => adopter.under_parent_node_seed(Zeroizing::new(*seed)),
            None => adopter,
        }
    }
